/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import java.util.Map;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.Text;import page2020.view.Value;import page2020.view.bs4.B4text.TextX;import page2020.view.html5.H5caption;import page2020.view.html5.H5col;import page2020.view.html5.H5colgroup;import page2020.view.html5.H5table;import page2020.view.html5.H5tbody;import page2020.view.html5.H5td;import page2020.view.html5.H5tfoot;import page2020.view.html5.H5th;import page2020.view.html5.H5thead;import page2020.view.html5.H5tr;public class B4table extends H5table {	public static final String responsive = "table-responsive";	public static final String table = "table";	public static final String small = "table-sm";	public static final String borderless = "table-borderless";	public static final String bordered = "table-bordered";	public static final String striped = "table-striped";	public static final String hover = "table-hover";	public static final String dark = "table-dark";	public static final String headLight = "thead-light";	public static final String headDark = "thead-dark";	public static final class TableColor {			public static final String primary = "table-primary";		public static final String secondary = "table-secondary";		public static final String success = "table-success";		public static final String warning = "table-warning";		public static final String danger = "table-danger";		public static final String info = "table-info";		public static final String dark = "table-dark";		public static final String light = "table-light";		public static final String active = "table-active";	}	public static final class TableBgHex {		public static final String primary = "#b8daff";		public static final String secondary = "#d6d8db";		public static final String success = "#c3e6cb";		public static final String warning = "#ffeeba";		public static final String danger = "#f5c6cb";		public static final String info = "#bee5eb";		public static final String dark = "#c6c8ca";		public static final String light = "#fdfdfe";		public static final String active = "rgba(0,0,0,.075)";			}	public static final class TheadColor {		public static final String dark = "thead-dark";		public static final String light = "thead-light";	}	public static String hex(String color) {		switch (color) {		case TableColor.primary:			return TableBgHex.primary;		case TableColor.secondary:			return TableBgHex.secondary;		case TableColor.success:			return TableBgHex.success;		case TableColor.warning:			return TableBgHex.warning;		case TableColor.danger:			return TableBgHex.danger;		case TableColor.info:			return TableBgHex.info;		case TableColor.dark:			return TableBgHex.dark;		case TableColor.light:			return TableBgHex.light;		case TableColor.active:			return TableBgHex.active;		default:			return "#FFFFFF";			}	}	private H5caption caption = null;	private H5colgroup colgroup = null;	private H5thead thead = null;	private H5tr header = null;	private H5tbody tbody = null;	private H5tfoot tfoot = null;	private H5tr row = null;	public B4table caption(Text text) {		if (this.caption == null) {			this.caption = new H5caption();			super.append(this.caption);		}		this.caption.append(text);		return this;	}	public B4table colgroup() {		if (this.colgroup == null) {			this.colgroup = new H5colgroup();			super.append(this.colgroup);		}		return this;	}	public B4table col(H5col col) {		if (this.colgroup == null) {			this.colgroup();		}		this.colgroup.append(col);		return this;	}	public B4table thead() {		if (this.thead == null) {			this.thead = new H5thead();			this.header = new H5tr();			super.append(this.thead.append(this.header));		}		return this;	}	public B4table headerColor(boolean light) {		thead();		if (light) {			this.header.cssClass(headLight);		} else {			this.header.cssClass(headDark);		}		return this;	}	public B4table nowrap() {		if (this.thead == null) {			this.thead();		}		this.header.cssClass(TextX.nowrap);		return this;	}	public H5th column(String code) {		if (this.thead == null) {			this.thead();		}		H5th th = new H5th();		this.header.append(th);		if (EmptyUtil.not(code)) {			th.code(code);		}		return th;	}	public H5th column(Value... styles) {		if (this.thead == null) {			this.thead();		}		H5th th = new H5th();		if (EmptyUtil.not((Object[]) styles)) {			th.css(styles);		}		this.header.append(th);		return th;	}	public B4table tbody() {		if (this.tbody == null) {			this.tbody = new H5tbody();			super.append(this.tbody);		}		return this;	}	public B4table tfoot() {		if (this.tfoot == null) {			this.tfoot = new H5tfoot();			super.append(this.tfoot);		}		return this;	}	public B4table row() {		if (this.tbody == null) {			this.tbody();		}		this.row = new H5tr();		this.tbody.append(this.row);		return this;	}	public B4table row(Object... data) {		this.row();		for (Object value : data) {			this.row.append(new H5td().value(value));		}		return this;	}	public B4table row(Map<?, ?> map) {		this.row();		for (Object key : map.keySet()) {			this.row.append(new H5td().value(map.get(key)));		}		return this;	}	public B4table col() {		if (this.row == null) {			this.row();		}		this.row.append(new H5td());		return this;	}	public B4table col(Object value) {		if (this.row == null) {			this.row();		}		this.row.append(new H5td().value(value));		return this;			}	public B4table small() {		super.cssClass(small);		return this;	}	public B4table borderless() {		super.cssClass(borderless);		return this;	}	public B4table bordered() {		super.cssClass(bordered);		return this;	}	public B4table striped() {		super.cssClass(striped);		return this;	}	public B4table hover() {		super.cssClass(hover);		return this;	}	public B4table dark() {		super.cssClass(dark);		return this;	}	@Override	public void build() {		super.build();	}	@Override	public B4table copy() {		B4table b4table = (B4table) super.copy();		for (Content<?> c : b4table.getContents()) {			if (c instanceof H5caption) {				b4table.setCaption((H5caption) c);			} else if (c instanceof H5colgroup) {				b4table.setColgroup((H5colgroup) c);			} else if (c instanceof H5thead) {				b4table.setThead((H5thead) c);			} else if (c instanceof H5tbody) {				b4table.setTbody((H5tbody) c);			} else if (c instanceof H5tfoot) {				b4table.setTfoot((H5tfoot) c);			}		}		this.header = null;		this.row = null;		return (B4table) b4table;	}	public H5caption getCaption() {		return caption;	}	public void setCaption(H5caption caption) {		this.caption = caption;	}	public H5colgroup getColgroup() {		return colgroup;	}	public void setColgroup(H5colgroup colgroup) {		this.colgroup = colgroup;	}	public H5thead getThead() {		return thead;	}	public void setThead(H5thead thead) {		this.thead = thead;	}	public H5tr getHeader() {		return header;	}	public void setHeader(H5tr header) {		this.header = header;	}	public H5tbody getTbody() {		return tbody;	}	public void setTbody(H5tbody tbody) {		this.tbody = tbody;	}	public H5tfoot getTfoot() {		return tfoot;	}	public void setTfoot(H5tfoot tfoot) {		this.tfoot = tfoot;	}	public H5tr getRow() {		return row;	}	public void setRow(H5tr row) {		this.row = row;	}}